  "test_path": "tests/test_cli_install_logging.py",
  "test": "import logging
import pytest
from browser_use import cli

class DummyResult:
    def __init__(self, code):
        self.returncode = code

def test_install_failure_logs_error(monkeypatch, caplog):
    # Mock subprocess.run to simulate a failure with return code 5
    def fake_run(_cmd):
        return DummyResult(5)
    monkeypatch.setattr(cli.subprocess, "run", fake_run)

    # Run the install command without help flags (triggers the failure path)
    ret = cli._run_install_command([])
    assert ret == 5

    # Verify that an error was logged
    error_messages = [rec.getMessage() for rec in caplog.records if rec.levelno == logging.ERROR]
    assert any('Installation failed' in msg for msg in error_messages), "Expected an error log for installation failure"
